[
  {
    "statement": "Studies have identified several methods for controlling disease and sea lice in Atlantic salmon farms.",
    "citations": []
  },
  {
    "statement": "For sea lice control, studies in Ireland found mixed effects of using cleaner wrasse.",
    "citations": []
  },
  {
    "statement": "Corkwing and goldskinny wrasse were as effective as chemical treatments for controlling sea lice.",
    "citations": []
  },
  {
    "statement": "Rockcook wrasse were ineffective at preventing lice outbreaks.",
    "citations": []
  },
  {
    "statement": "Altering lighting intensity was found to reduce lice numbers in Atlantic salmon.",
    "citations": []
  },
  {
    "statement": "Lower intensity artificial light or natural lighting resulted in fewer lice.",
    "citations": []
  },
  {
    "statement": "Fallowing systems showed mixed results for controlling lice and disease.",
    "citations": []
  },
  {
    "statement": "A study in Scotland recorded lower lice numbers in salmon farms that used fallowing systems.",
    "citations": []
  },
  {
    "statement": "A study in Australia found no difference in salmon mortality from Amoebic Gill Disease when using fallowing systems.",
    "citations": []
  },
  {
    "statement": "For disease prevention and control, vaccinations were found to increase salmon survival rates against various pathogens.",
    "citations": []
  },
  {
    "statement": "Vaccinations increased survival rates against pathogens including Aeromonas salmonicida spp.",
    "citations": []
  },
  {
    "statement": "achromogenes, Yersinia ruckeri, marine flexibacteriosis, bacterial kidney disease, and infectious salmon anaemia.",
    "citations": []
  },
  {
    "statement": "Using probiotics and immunostimulants showed benefits including increased survival when salmon were exposed to disease-causing bacteria.",
    "citations": []
  },
  {
    "statement": "One study found a 28% reduction in lice infection when fish were fed a diet with 28% plant-based protein.",
    "citations": []
  },
  {
    "statement": "A further 28% reduction in lice infection occurred when beta-glucans were added to the salmon's diet.",
    "citations": []
  },
  {
    "statement": "Freshwater bathing to reduce amoebic gill disease in salmon showed mixed results.",
    "citations": []
  },
  {
    "statement": "One study found that freshwater bathing reduced amoebae on salmon gills for up to 10 days.",
    "citations": []
  },
  {
    "statement": "Another study found no difference in amoebic gill disease between salmon that were treated with freshwater baths and untreated salmon.",
    "citations": []
  }
]

[
  {
    "statement": "Based on multiple studies from Norway, plant-based protein alternatives to fish meal generally result in decreased growth rates in Atlantic salmon.",
    "citations": []
  },
  {
    "statement": "Six studies found reduced growth rates in Atlantic salmon with plant-based diets.",
    "citations": []
  },
  {
    "statement": "Three studies found similar growth rates in Atlantic salmon with plant-based diets compared to fish meal controls.",
    "citations": []
  },
  {
    "statement": "Plant-based diets showed reduced final body weights of Atlantic salmon in four studies.",
    "citations": []
  },
  {
    "statement": "Plant-based diets for Atlantic salmon had mixed effects on feeding efficiency.",
    "citations": []
  },
  {
    "statement": "Some studies showed that plant-based diets lowered feeding efficiency in Atlantic salmon, while other studies showed increased efficiency.",
    "citations": []
  },
  {
    "statement": "Studies on the reduction of fish meal in Atlantic salmon diets found no significant differences in final weights.",
    "citations": []
  },
  {
    "statement": "Bacterial protein alternatives to fish meal showed more favorable results for Atlantic salmon growth.",
    "citations": []
